The pattern or idea this question is really about: Using mathematical properties (GCD) to shortcut string pattern matching.

THE BEST SOLUTION

C++
#include <string>
#include <numeric>

using namespace std;

class Solution {
public:
    string gcdOfStrings(string str1, string str2) {
        if (str1 + str2 != str2 + str1) {
            return "";
        }

        int gcdLength = std::gcd(str1.length(), str2.length());
        return str1.substr(0, gcdLength);
    }
};
